           ].join("")
         );
       }

       function App() {
         return h(
           "main",
           { className: "page" },
           h(
             "section",
             { className: "support-card", "aria-labelledby": "support-title" },
             [
               h("p", { className: "eyebrow" }, "Support"),
               h("h1", { id: "support-title" }, "Contact our support team"),
               h(
                 "p",
                 { className: "lead" },
                 "Send us a message and we’ll get back to you as soon as possible."
               ),
               h(
                 "form",
                 { id: "contact-form", novalidate: true },
                 [
                   renderField("fullName"),
                   renderField("email"),
                   renderField("phone"),
                   h("p", { className: "status", id: "form-status", role: "status", "aria-live": "polite" }, state.success),
                   h("div", { className: "actions" }, h("button", { type: "submit" }, "Send message")),
                 ].join("")
               ),
             ].join("")
           )
         );
       }

       function syncInputs() {
         document.querySelectorAll("input").forEach((input) => {
           input.value = state.values[input.name] ?? "";
         });
       }

       function render() {
         document.getElementById("root").innerHTML = App();
         syncInputs();

         document.querySelectorAll("input").forEach((input) => {
           input.addEventListener("input", (event) => {
             state.values[event.target.name] = event.target.value;
           });
         });

         document.getElementById("contact-form").addEventListener("submit", (event) => {
           event.preventDefault();
           state.submitted = true;
           state.errors = validate(state.values);

           if (Object.keys(state.errors).length === 0) {
             state.success = "Thanks — your message is ready to send.";
           } else {
             state.success = "";
           }

           render();
         });
       }

       render();
     </script>
   </body>
 </html>

')
